package main

import (
	"bufio"
	"os"
	"path/filepath"
	"strings"
)

type Icons struct {
	fileTypes  map[string]string
	extensions map[string]string
	filenames  map[string]string
	patterns   map[string]string
}

func LoadIcons(path string) (*Icons, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	icons := &Icons{
		fileTypes:  make(map[string]string),
		extensions: make(map[string]string),
		filenames:  make(map[string]string),
		patterns:   make(map[string]string),
	}

	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := scanner.Text()
		line = strings.Split(line, "#")[0]
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}

		parts := strings.Fields(line)
		if len(parts) < 2 {
			continue
		}

		pattern := parts[0]
		icon := parts[1]

		if strings.HasPrefix(pattern, "*.") {
			icons.extensions[pattern[2:]] = icon
		} else if strings.HasPrefix(pattern, "*") {
			icons.filenames[pattern[1:]] = icon
		} else if len(pattern) == 2 {
            // Probably file types like "di", "fi", etc.
			icons.fileTypes[pattern] = icon
		} else {
			icons.filenames[pattern] = icon
		}
	}

	return icons, scanner.Err()
}

func (icons *Icons) Get(info os.FileInfo) string {
	name := info.Name()

    // 1. Check filename
	if icon, ok := icons.filenames[name]; ok {
		return icon
	}
    if icon, ok := icons.filenames[strings.ToLower(name)]; ok {
        return icon
    }

	// 2. Check extension
	ext := filepath.Ext(name)
	if ext != "" {
		if icon, ok := icons.extensions[ext[1:]]; ok {
			return icon
		}
        if icon, ok := icons.extensions[strings.ToLower(ext[1:])]; ok {
            return icon
        }
	}

	// 3. Check file type
	mode := info.Mode()
	if info.IsDir() {
		return icons.fileTypes["di"]
	}
	if mode&os.ModeSymlink != 0 {
		return icons.fileTypes["ln"]
	}
	if mode&os.ModeSocket != 0 {
		return icons.fileTypes["so"]
	}
	if mode&os.ModeNamedPipe != 0 {
		return icons.fileTypes["pi"]
	}
	if mode&os.ModeDevice != 0 {
		if mode&os.ModeCharDevice != 0 {
			return icons.fileTypes["cd"]
		}
		return icons.fileTypes["bd"]
	}
    if mode&0111 != 0 {
        return icons.fileTypes["ex"]
    }

	return icons.fileTypes["fi"]
}
EOF
"}

