{"command":"cat <<'EOF' > status.go
package main

import (
	"fmt"
	"io/fs"
	"os"
	"os/user"
	"strconv"
	"strings"
	"syscall"
	"time"

	"github.com/expr-lang/expr"
)

type FileInfo struct {
	fs.DirEntry
	info os.FileInfo
}

func (f FileInfo) Size() string {
	if f.IsDir() {
		return ""
	}
	size := f.info.Size()
	const unit = 1024
	if size < unit {
		return fmt.Sprintf("%d B", size)
	}
	div, exp := int64(unit), 0
	for n := size / unit; n >= unit; n /= unit {
		div *= unit
		exp++
	}
	return fmt.Sprintf("%.1f %cB", float64(size)/float64(div), "KMGTPE"[exp])
}

func (f FileInfo) Mode() string {
	return f.info.Mode().String()
}

func (f FileInfo) ModTime() string {
	return f.info.ModTime().Format("Jan _2 15:04")
}

func (f FileInfo) Owner() string {
	stat := f.info.Sys().(*syscall.Stat_t)
	u, err := user.LookupId(strconv.Itoa(int(stat.Uid)))
	username := strconv.Itoa(int(stat.Uid))
	if err == nil {
		username = u.Username
	}
	g, err := user.LookupGroupId(strconv.Itoa(int(stat.Gid)))
	groupname := strconv.Itoa(int(stat.Gid))
	if err == nil {
		groupname = g.Name
	}
	return username + ":" + groupname
}

func (f FileInfo) PadLeft(s string, n int) string {
	if len(s) >= n {
		return s
	}
	return strings.Repeat(" ", n-len(s)) + s
}

func (f FileInfo) PadRight(s string, n int) string {
	if len(s) >= n {
		return s
	}
	return s + strings.Repeat(" ", n-len(s))
}

func evaluateStatus(expression string, current FileInfo, files []FileInfo) string {
	env := map[string]interface{}{
		"current_file": current,
		"files":        files,
		"Size":         current.Size,
		"Mode":         current.Mode,
		"ModTime":      current.ModTime,
		"Owner":        current.Owner,
		"PadLeft":      current.PadLeft,
		"PadRight":     current.PadRight,
		"Sprintf":      fmt.Sprintf,
		"join":         strings.Join,
	}

	program, err := expr.Compile(expression, expr.Env(env))
	if err != nil {
		return err.Error()
	}

	output, err := expr.Run(program, env)
	if err != nil {
		return err.Error()
	}

	return fmt.Sprint(output)
}
EOF
"}

