{"command":"cat <<'EOF' > main.go
package main

import (
	"flag"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/gdamore/tcell/v2"
	"github.com/mattn/go-runewidth"
)

var (
	showIcons    = flag.Bool("icons", false, "display icons")
	dirOnly      = flag.Bool("dir-only", false, "show dirs only")
	hideHidden   = flag.Bool("hide-hidden", false, "hide hidden files")
	showPreview  = flag.Bool("preview", false, "display preview")
	withBorder   = flag.Bool("with-border", false, "preview with border")
	fuzzyMode    = flag.Bool("fuzzy", false, "fuzzy mode")
	version      = "v1.13.0"
)

type State struct {
	path        string
	entries     []FileInfo
	cursor      int
	scroll      int
	width       int
	height      int
	screen      tcell.Screen
	icons       *Icons
	preview     bool
	hidden      bool
	search      string
	searching   bool
	selected    string
	exitWithCd  bool
	statusBar   string
}

func main() {
	flag.Usage = func() {
		fmt.Printf(`
  walk %s

  Usage: walk [path]

    arrows, hjkl  Move cursor
    enter         Enter directory
    backspace     Exit directory
    space         Toggle preview
    esc, q        Exit with cd
    ctrl+c        Exit without cd
    /             Fuzzy search
    d, delete     Delete file or dir
    y             Copy to clipboard
    .             Hide hidden files
    ?             Show help

  Flags:
`, version)
		flag.PrintDefaults()
	}
	flag.Parse()

	startPath := "."
	if flag.NArg() > 0 {
		startPath = flag.Arg(0)
	}

	absPath, err := filepath.Abs(startPath)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	state := &State{
		path:       absPath,
		preview:    *showPreview,
		hidden:     *hideHidden,
		statusBar:  os.Getenv("WALK_STATUS_BAR"),
	}
    if state.statusBar == "" {
        state.statusBar = `[Mode(), Owner(), Size() | PadLeft(7), ModTime() | PadLeft(12)] | join(" ")`
    }

	if *showIcons {
		state.icons, _ = LoadIcons("etc/icons")
	}

	s, err := tcell.NewScreen()
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if err := s.Init(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	state.screen = s
	defer s.Fini()

	state.loadDir()

	for {
		state.draw()
		ev := s.PollEvent()
		switch ev := ev.(type) {
		case *tcell.EventKey:
			if state.searching {
				state.handleSearchKey(ev)
			} else {
				if quit := state.handleKey(ev); quit {
					if state.exitWithCd {
						s.Fini()
						fmt.Println(state.selected)
						return
					}
					return
				}
			}
		case *tcell.EventResize:
			state.width, state.height = s.Size()
			s.Sync()
		}
	}
}

func (s *State) loadDir() {
	entries, err := os.ReadDir(s.path)
	if err != nil {
		return
	}

	s.entries = nil
	for _, entry := range entries {
		if s.hidden && strings.HasPrefix(entry.Name(), ".") {
			continue
		}
		if *dirOnly && !entry.IsDir() {
			continue
		}
		info, _ := entry.Info()
		s.entries = append(s.entries, FileInfo{entry, info})
	}

	sort.Slice(s.entries, func(i, j int) bool {
		if s.entries[i].IsDir() != s.entries[j].IsDir() {
			return s.entries[i].IsDir()
		}
		return strings.ToLower(s.entries[i].Name()) < strings.ToLower(s.entries[j].Name())
	})

	if s.cursor >= len(s.entries) {
		s.cursor = len(s.entries) - 1
	}
	if s.cursor < 0 {
		s.cursor = 0
	}
}

func (s *State) draw() {
	s.screen.Clear()
	s.width, s.height = s.screen.Size()

	listWidth := s.width
	if s.preview {
		listWidth = s.width / 2
	}

	// Draw list
	for i := 0; i < s.height-1; i++ {
		idx := i + s.scroll
		if idx >= len(s.entries) {
			break
		}

		entry := s.entries[idx]
		style := tcell.StyleDefault
		if idx == s.cursor {
			style = style.Reverse(true)
		}

		icon := ""
		if s.icons != nil {
			icon = s.icons.Get(entry.info) + " "
		}

		name := entry.Name()
		if entry.IsDir() {
			name += "/"
		}

		line := icon + name
		s.drawString(0, i, style, line, listWidth)
	}

	// Draw preview
	if s.preview && len(s.entries) > 0 {
		s.drawPreview(listWidth, 0, s.width-listWidth, s.height-1)
	}

	// Draw status bar or search prompt
	if s.searching {
		s.drawString(0, s.height-1, tcell.StyleDefault, "/"+s.search, s.width)
	} else if len(s.entries) > 0 {
		status := evaluateStatus(s.statusBar, s.entries[s.cursor], s.entries)
		s.drawString(0, s.height-1, tcell.StyleDefault, status, s.width)
	}

	s.screen.Show()
}

func (s *State) drawString(x, y int, style tcell.Style, str string, maxWidth int) {
	currX := x
	for _, r := range str {
		w := runewidth.RuneWidth(r)
		if currX+w > x+maxWidth {
			break
		}
		s.screen.SetContent(currX, y, r, nil, style)
		currX += w
	}
}

func (s *State) drawPreview(x, y, w, h int) {
	if s.cursor >= len(s.entries) {
		return
	}
	entry := s.entries[s.cursor]
	path := filepath.Join(s.path, entry.Name())

	style := tcell.StyleDefault
	if *withBorder {
		for i := 0; i < h; i++ {
			s.screen.SetContent(x, y+i, '│', nil, style)
		}
		x++
		w--
	}

	if entry.IsDir() {
		subEntries, _ := os.ReadDir(path)
		for i, sub := range subEntries {
			if i >= h {
				break
			}
			name := sub.Name()
			if sub.IsDir() {
				name += "/"
			}
			s.drawString(x, y+i, style, name, w)
		}
	} else {
		content, _ := os.ReadFile(path)
		lines := strings.Split(string(content), "\n")
		for i, line := range lines {
			if i >= h {
				break
			}
			s.drawString(x, y+i, style, line, w)
		}
	}
}

func (s *State) handleKey(ev *tcell.EventKey) bool {
	switch ev.Key() {
	case tcell.KeyRune:
		switch ev.Rune() {
		case 'q':
			if len(s.entries) > 0 {
				s.selected = filepath.Join(s.path, s.entries[s.cursor].Name())
			} else {
				s.selected = s.path
			}
			s.exitWithCd = true
			return true
		case 'j':
			s.moveCursor(1)
		case 'k':
			s.moveCursor(-1)
		case 'h':
			s.goUp()
		case 'l':
