			}
		}
		// Adjust scroll
		if s.cursor >= s.scroll+s.height-1 {
			s.scroll = s.cursor - (s.height - 2)
		}
	}
}

func (s *State) handleSearchKey(ev *tcell.EventKey) {
	switch ev.Key() {
	case tcell.KeyEnter, tcell.KeyEsc:
		s.searching = false
	case tcell.KeyBackspace, tcell.KeyBackspace2:
		if len(s.search) > 0 {
			s.search = s.search[:len(s.search)-1]
			s.updateSearch()
		} else {
			s.searching = false
		}
	case tcell.KeyRune:
		s.search += string(ev.Rune())
		s.updateSearch()
	}
}

func (s *State) updateSearch() {
	for i, entry := range s.entries {
		if strings.Contains(strings.ToLower(entry.Name()), strings.ToLower(s.search)) {
			s.cursor = i
			// Adjust scroll
			if s.cursor < s.scroll {
				s.scroll = s.cursor
			} else if s.cursor >= s.scroll+s.height-1 {
				s.scroll = s.cursor - (s.height - 2)
			}
			break
		}
	}
}
