{"command":"cat <<'EOF' > main.go
package main

import (
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"syscall"
	"unsafe"
)

var (
	showIcons    = flag.Bool("icons", false, "display icons")
	dirOnly      = flag.Bool("dir-only", false, "show dirs only")
	hideHidden   = flag.Bool("hide-hidden", false, "hide hidden files")
	showPreview  = flag.Bool("preview", false, "display preview")
	withBorder   = flag.Bool("with-border", false, "preview with border")
	fuzzyMode    = flag.Bool("fuzzy", false, "fuzzy mode")
	version      = "v1.13.0"
)

type State struct {
	path        string
	entries     []FileInfo
	cursor      int
	scroll      int
	width       int
	height      int
	icons       *Icons
	preview     bool
	hidden      bool
	search      string
	searching   bool
	selected    string
	exitWithCd  bool
	statusBar   string
}

func main() {
	flag.Usage = func() {
		fmt.Printf(`
  walk %s

  Usage: walk [path]

    arrows, hjkl  Move cursor
    enter         Enter directory
    backspace     Exit directory
    space         Toggle preview
    esc, q        Exit with cd
    ctrl+c        Exit without cd
    /             Fuzzy search
    d, delete     Delete file or dir
    y             Copy to clipboard
    .             Hide hidden files
    ?             Show help

  Flags:
`, version)
		flag.PrintDefaults()
	}
	flag.Parse()

	startPath := "."
	if flag.NArg() > 0 {
		startPath = flag.Arg(0)
	}

	absPath, err := filepath.Abs(startPath)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	state := &State{
		path:      absPath,
		preview:   *showPreview,
		hidden:    *hideHidden,
		statusBar: os.Getenv("WALK_STATUS_BAR"),
	}
	if state.statusBar == "" {
		state.statusBar = `[Mode(), Owner(), Size() | PadLeft(7), ModTime() | PadLeft(12)] | join(" ")`
	}

	if *showIcons {
		state.icons, _ = LoadIcons("etc/icons")
	}

	oldTermios, err := setRawMode()
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer restoreMode(oldTermios)

	fmt.Print("\033[?1049h") // Alternate buffer
	fmt.Print("\033[?25l")   // Hide cursor
	defer fmt.Print("\033[?25h")
	defer fmt.Print("\033[?1049l")

	state.loadDir()

	for {
		state.width, state.height = getTermSize()
		state.draw()

		buf := make([]byte, 16)
		n, err := os.Stdin.Read(buf)
		if err != nil {
			break
		}

		if quit := state.handleInput(buf[:n]); quit {
			if state.exitWithCd {
				restoreMode(oldTermios)
				fmt.Print("\033[?25h")
				fmt.Print("\033[?1049l")
				fmt.Println(state.selected)
				os.Exit(0)
			}
			return
		}
	}
}

func setRawMode() (*syscall.Termios, error) {
	var old syscall.Termios
	if _, _, err := syscall.Syscall(syscall.SYS_IOCTL, os.Stdin.Fd(), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&old))); err != 0 {
		return nil, err
	}
	new := old
	new.Lflag &^= syscall.ICANON | syscall.ECHO | syscall.ISIG
	if _, _, err := syscall.Syscall(syscall.SYS_IOCTL, os.Stdin.Fd(), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&new))); err != 0 {
		return nil, err
	}
	return &old, nil
}

func restoreMode(old *syscall.Termios) {
	if old != nil {
		_, _, _ = syscall.Syscall(syscall.SYS_IOCTL, os.Stdin.Fd(), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(old)))
	}
}

func getTermSize() (int, int) {
	var sz struct {
		rows, cols, xpixel, ypixel uint16
	}
	_, _, _ = syscall.Syscall(syscall.SYS_IOCTL,
		os.Stdout.Fd(), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&sz)))
	return int(sz.cols), int(sz.rows)
}

func (s *State) loadDir() {
	entries, err := os.ReadDir(s.path)
	if err != nil {
		return
	}

	s.entries = nil
	for _, entry := range entries {
		if s.hidden && strings.HasPrefix(entry.Name(), ".") {
			continue
		}
		if *dirOnly && !entry.IsDir() {
			continue
		}
		info, _ := entry.Info()
		if info == nil { continue }
		s.entries = append(s.entries, FileInfo{entry, info})
	}

	sort.Slice(s.entries, func(i, j int) bool {
		if s.entries[i].IsDir() != s.entries[j].IsDir() {
			return s.entries[i].IsDir()
		}
		return strings.ToLower(s.entries[i].Name()) < strings.ToLower(s.entries[j].Name())
	})

	if s.cursor >= len(s.entries) {
		s.cursor = len(s.entries) - 1
	}
	if s.cursor < 0 {
		s.cursor = 0
	}
}

func (s *State) draw() {
	fmt.Print("\033[H") // Move to 0,0

	listWidth := s.width
	if s.preview {
		listWidth = s.width / 2
	}

	for i := 0; i < s.height-1; i++ {
		idx := i + s.scroll
		if idx >= len(s.entries) {
			// Clear rest of line
			fmt.Printf("\033[%d;1H\033[K", i+1)
			continue
		}

		entry := s.entries[idx]
		prefix := ""
		suffix := ""
		if idx == s.cursor {
			prefix = "\033[7m"
			suffix = "\033[0m"
		}

		icon := ""
		if s.icons != nil {
			icon = s.icons.Get(entry.info) + " "
		}

		name := entry.Name()
		if entry.IsDir() {
			name += "/"
		}

		line := icon + name
		if len(line) > listWidth {
			line = line[:listWidth]
		}
		fmt.Printf("\033[%d;1H%s%-*s%s", i+1, prefix, listWidth, line, suffix)
	}

	if s.preview && len(s.entries) > 0 {
		s.drawPreview(listWidth + 1, 1, s.width-listWidth, s.height-1)
	}

	// Status bar
	fmt.Printf("\033[%d;1H\033[K", s.height)
	if s.searching {
		fmt.Printf("/%s", s.search)
	} else if len(s.entries) > 0 {
		status := evaluateStatus(s.statusBar, s.entries[s.cursor], s.entries)
		if len(status) > s.width {
			status = status[:s.width]
		}
		fmt.Print(status)
	}
}

func (s *State) drawPreview(x, y, w, h int) {
	entry := s.entries[s.cursor]
	path := filepath.Join(s.path, entry.Name())

	border := ""
	if *withBorder {
		border = "│"
		w--
	}

	if entry.IsDir() {
		subEntries, _ := os.ReadDir(path)
		for i := 0; i < h; i++ {
			fmt.Printf("\033[%d;%dH%s", y+i, x, border)
			if i < len(subEntries) {
				name := subEntries[i].Name()
				if subEntries[i].IsDir() {
					name += "/"
				}
				if len(name) > w { name = name[:w] }
				fmt.Printf("%-*s", w, name)
			} else {
				fmt.Printf("%-*s", w, "")
			}
		}
	} else {
		content, _ := os.ReadFile(path)
		lines := strings.Split(string(content), "\n")
		for i := 0; i < h; i++ {
			fmt.Printf("\033[%d;%dH%s", y+i, x, border)
			if i < len(lines) {
				line := lines[i]
				if len(line) > w { line = line[:w] }
				fmt.Printf("%-*s", w, line)
			} else {
				fmt.Printf("%-*s", w, "")
			}
		}
	}
}

func (s *State) handleInput(buf []byte) bool {
	if s.searching {
		return s.handleSearchInput(buf)
	}

	if len(buf) == 1 {
		switch buf[0] {
		case 'q':
			if len(s.entries) > 0 {
				s.selected = filepath.Join(s.path, s.entries[s.cursor].Name())
			} else {
				s.selected = s.path
			}
			s.exitWithCd = true
			return true
		case 'j':
			s.moveCursor(1)
		case 'k':
			s.moveCursor(-1)
		case 'h':
			s.goUp()
		case 'l':
			s.enterDir()
		case ' ':
			s.preview = !s.preview
		case '.':
			s.hidden = !s.hidden
			s.loadDir()
		case '/':
			s.searching = true
			s.search = ""
		case '\r', '\n':
			s.enterDir()
		case 127: // Backspace
			s.goUp()
		case 27: // Esc
			if len(s.entries) > 0 {
				s.selected = filepath.Join(s.path, s.entries[s.cursor].Name())
			} else {
				s.selected = s.path
			}
			s.exitWithCd = true
			return true
		case 3: // Ctrl+C
			return true
		}
	} else if len(buf) >= 3 && buf[0] == 27 && buf[1] == '[' {
		switch buf[2] {
		case 'A': // Up
			s.moveCursor(-1)
		case 'B': // Down
			s.moveCursor(1)
		}
	}
	return false
}

func (s *State) handleSearchInput(buf []byte) bool {
	if len(buf) == 1 {
		switch buf[0] {
		case '\r', '\n', 27:
			s.searching = false
		case 127:
			if len(s.search) > 0 {
				s.search = s.search[:len(s.search)-1]
				s.updateSearch()
			} else {
				s.searching = false
			}
		default:
			if buf[0] >= 32 && buf[0] <= 126 {
				s.search += string(buf[0])
				s.updateSearch()
			}
		}
	}
	return false
}

func (s *State) moveCursor(n int) {
	s.cursor += n
	if s.cursor < 0 {
		s.cursor = 0
	}
	if s.cursor >= len(s.entries) {
		s.cursor = len(s.entries) - 1
	}
	if s.cursor < s.scroll {
		s.scroll = s.cursor
	} else if s.cursor >= s.scroll+s.height-1 {
		s.scroll = s.cursor - (s.height - 2)
	}
}

func (s *State) enterDir() {
	if len(s.entries) == 0 {
		return
	}
	entry := s.entries[s.cursor]
	if entry.IsDir() {
		newPath := filepath.Join(s.path, entry.Name())
		s.path = newPath
		s.cursor = 0
		s.scroll = 0
		s.loadDir()
	}
}

func (s *State) goUp() {
	parent := filepath.Dir(s.path)
	if parent != s.path {
		oldBase := filepath.Base(s.path)
		s.path = parent
		s.loadDir()
		for i, entry := range s.entries {
			if entry.Name() == oldBase {
				s.cursor = i
				break
			}
		}
		if s.cursor >= s.scroll+s.height-1 {
			s.scroll = s.cursor - (s.height - 2)
		}
	}
}

func (s *State) updateSearch() {
	for i, entry := range s.entries {
		if strings.Contains(strings.ToLower(entry.Name()), strings.ToLower(s.search)) {
			s.cursor = i
			if s.cursor < s.scroll {
				s.scroll = s.cursor
			} else if s.cursor >= s.scroll+s.height-1 {
				s.scroll = s.cursor - (s.height - 2)
			}
			break
		}
	}
}
EOF
"}

