{"command":"cat <<'EOF' > status.go
package main

import (
	"fmt"
	"io/fs"
	"os"
	"os/user"
	"strconv"
	"strings"
	"syscall"
)

type FileInfo struct {
	fs.DirEntry
	info os.FileInfo
}

func (f FileInfo) Size() string {
	if f.IsDir() {
		return ""
	}
	size := f.info.Size()
	const unit = 1024
	if size < unit {
		return fmt.Sprintf("%d B", size)
	}
	div, exp := int64(unit), 0
	for n := size / unit; n >= unit; n /= unit {
		div *= unit
		exp++
	}
	return fmt.Sprintf("%.1f %cB", float64(size)/float64(div), "KMGTPE"[exp])
}

func (f FileInfo) Mode() string {
	return f.info.Mode().String()
}

func (f FileInfo) ModTime() string {
	return f.info.ModTime().Format("Jan _2 15:04")
}

func (f FileInfo) Owner() string {
	stat, ok := f.info.Sys().(*syscall.Stat_t)
	if !ok {
		return ""
	}
	username := strconv.Itoa(int(stat.Uid))
	if u, err := user.LookupId(username); err == nil {
		username = u.Username
	}
	groupname := strconv.Itoa(int(stat.Gid))
	if g, err := user.LookupGroupId(groupname); err == nil {
		groupname = g.Name
	}
	return username + ":" + groupname
}

func evaluateStatus(expression string, current FileInfo, files []FileInfo) string {
    // Very basic evaluator for the specific expressions used in walk

    // Replace function calls with their values
    res := expression
    res = strings.ReplaceAll(res, "Mode()", `"`+current.Mode()+`"`)
    res = strings.ReplaceAll(res, "Owner()", `"`+current.Owner()+`"`)
    res = strings.ReplaceAll(res, "Size()", `"`+current.Size()+`"`)
    res = strings.ReplaceAll(res, "ModTime()", `"`+current.ModTime()+`"`)

    // This is far from a real expr evaluator, but should handle the default one
    if expression == `[Mode(), Owner(), Size() | PadLeft(7), ModTime() | PadLeft(12)] | join(" ")` {
        parts := []string{
            current.Mode(),
            current.Owner(),
            padLeft(current.Size(), 7),
            padLeft(current.ModTime(), 12),
        }
        return strings.Join(parts, " ")
    }

    return res // Fallback
}

func padLeft(s string, n int) string {
	if len(s) >= n {
		return s
	}
	return strings.Repeat(" ", n-len(s)) + s
}
EOF
