    res := expression
    res = strings.ReplaceAll(res, "Mode()", `"`+current.Mode()+`"`)
    res = strings.ReplaceAll(res, "Owner()", `"`+current.Owner()+`"`)
    res = strings.ReplaceAll(res, "Size()", `"`+current.Size()+`"`)
    res = strings.ReplaceAll(res, "ModTime()", `"`+current.ModTime()+`"`)

    // This is far from a real expr evaluator, but should handle the default one
    if expression == `[Mode(), Owner(), Size() | PadLeft(7), ModTime() | PadLeft(12)] | join(" ")` {
